"""Bind completed human mathematical review to exact current article passages."""
from pathlib import Path
import json,hashlib

ROOT=Path(__file__).resolve().parents[4];HERE=Path(__file__).resolve().parent;TASK=HERE.parent
FAMILY=ROOT/'integrals/families/three-loop-insertions'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()

def evidence(p,needle,role):
    lines=p.read_text(encoding='utf-8-sig').splitlines();matches=[(i+1,line) for i,line in enumerate(lines) if needle in line]
    assert matches,(p,needle);line,passage=matches[0]
    return {'path':p.relative_to(ROOT).as_posix(),'line':line,'passage':passage,'role':role,'file_sha256':sha(p)}

def main():
    replay=read(TASK/'replay.json');assert replay['status']=='passed'
    transcription=read(HERE/'math-transcription-check.json');assert transcription['status']=='passed'
    for item in transcription['checks']:assert sha(ROOT/item['new_markdown'])==item['new_markdown_sha256']
    ids=[f'4e-Pi1-{i:02}' for i in range(1,12)]+['2e-Pi1+Pi1-01','2e-Pi1+Pi1-02','2e-Pi2-01','2e-Pi2-02']
    routes={1:'P1',2:'P1',3:'P3',4:'P4',5:'P2',6:'P2',7:'P5',8:'P5',9:'P4',10:'P3',11:'P6'}
    descriptions={
      1:('Actual two ordered endpoint chains with insertion on the lower labelled line give rates3e,e and3e,2e; their product gives J=z^(3e)/[18e^4(1+e)]. Native connected C then fixes the negative scalar and fifth-order finite convolution.',r'J=\frac{z^{3e}}{1+e}',r'1/(3e^2)'),
      2:('The upper labelled insertion exchanges the two chain exponents. Both own bracket integrals are evaluated, giving the same J without assuming final-table equality; physical orbit/crossing follows with this source C.',r'x^{e-1}y^{2e-1}',r'1/(6e^2)'),
      3:('Actual bare endpoint integrations leave1-t^e. The complete mixed derivative produces the retained boundary1+z^(2e)/3-Q, alongside the evaluated weighted opposite body, before current-C assembly.',r'1+z^{2e}/3-Q',r'\frac{\cosh(e\rho/2)'),
      4:('The full adjacent insertion is integrated on the actual ordered interval. Its1-t^(2e) weight gives B(e,0)-B(e,2e), with both even and odd reciprocal H channels kept in the finite coefficient.',r'1-t^{2e}',r'\cosh(e\rho)'),
      5:('Three elementary primitives expose the remaining Beta difference1/(2e)-B(2e,1+e), giving its own z^e root. The source cancellation1-Q=O(e²) reduces the pole before operator convolution.',r'1/(2e)-B(2e,1+e)',r'\frac{z^e(1-Q)}'),
      6:('The insertion on the other actual line gives1/e-B(e,1+2e) and the distinct z^(2e) phase. Reciprocal pairing gives the same physical I as05 while preserving its different bare J.',r'1/e-B(e,1+2e)',r'\frac{z^{2e}(1-Q)}'),
      7:('The lower-endpoint insertion is integrated over its actual inner rectangle, retaining its four signed corners. Combined with the explicit outer rectangle of08, the eight evaluated square terms give A; the mixed T sum uses precisely2rho0+3e rho1 to the required order.',r'D_z(s_2,t_2)^{2e}',r'c_0=-\rho^2M_{0,1}/512'),
      8:('The upper-endpoint insertion gives its own outer rectangle z^(2e)-(zs1)^(2e)-(zt1)^(2e)+D1^(2e). The explicit ordered-chain reflection proves a complete-I relation to07; it is not an independent-square factorization.',r'z^{2e}-(zs_1)^{2e}',r'T(2e,e)+T(e,2e)'),
      9:('Its own adjacent lower primitive is1-(1-x)^(2e). The concrete complement map preserves insertion/bare labels and dependent bounds and proves J09=z^(3e)J04(1/z), then the physical paired I relation.',r'(s_{21},s_{41},s_{42},s_{31})_{04}',r'J_{09}=z^{3e}'),
      10:('The own bare endpoint integral leaves1-(1-x)^e. The explicit complement map and separate line scalings prove J10=z^(3e)J03(1/z), retaining the mapped nonzero derivative/Beta boundary.',r'(s_{21},s_{41},s_{42},s_{31})_{03}',r'z^{-2e}'),
      11:('The actual endpoint domain factors into two independent squares. Complementing the reverse insertion gives D, while its four derivative corners give1+z^(2e). This boundary remains in the product and supplies its double pole.',r'z^{2e}-0-0+1',r'\quad K=\frac{H_0^{(1)}')}
    rows=[]
    for oid in ids:
        own=ROOT/'integrals/three-loop'/oid;p=own/'derivation.md';inp=read(own/'input.json');data=read(own/'data/index.json')
        ev=[];direct=False
        if oid.startswith('4e-Pi1'):
            number=int(oid[-2:]);route=routes[number];chain,first,second=descriptions[number];direct=route in ('P1','P2')
            ev += [evidence(p,'$$ F=','complete actual insertion distance'),evidence(p,'original outer-to-inner order','original prescribed ordered domain'),evidence(p,first,'graph-specific integration or mapped boundary'),evidence(p,second,'specific primitive, evaluation or complete-source scaling'),evidence(p,r'c_0=\frac{ma_1}{64}','complete highest-order source/prefactor convolution'),evidence(p,'finite term is sum(phi_X,n','full epsilon-dependent external-colour convolution')]
            shared=FAMILY/'pi1.md'
            ev.append(evidence(shared,'Its absolute density is therefore bounded','corrected absolute-integrability bound for full transverse numerator'))
            if not direct:
                ev += [evidence(shared,r'[\nu^q]H','actual finite evaluated moment rule'),evidence(FAMILY/'appendices/pi1-moments.md','M_0_1 =','complete adopted moment HLOG value')]
            if route=='P5':ev += [evidence(shared,'T(2e,e)+T(e,2e)=2','precise mixed-body first derivative'),evidence(FAMILY/'appendices/pi1-moments.md','rho1 =','complete adopted ordered-body HLOG value')]
            adoption='Prepared Fourier/QFT root and connected projection are accepted; '+('no evaluated M/rho function is mathematically needed by this Gamma/Beta body.' if direct else 'required evaluated M functions and, for P5, exact diagonal rho0/rho1 are precisely adopted with kernels, domain, order and full values exposed.')
            equality='01/02 have directly evaluated equal bare J;05/06 have different bare-z phases but equal physical I;03/10,04/09,07/08 are complete-I reciprocal-source relations with explicit maps. The present entry uses only its applicable relation.'
        else:
            opposite=oid.endswith('02');pi2=oid.startswith('2e-Pi2');route=('Pi2' if pi2 else 'serial Pi1')+('-opposite' if opposite else '-adjacent');direct=not opposite
            chain='One full transverse '+('two-loop1PI' if pi2 else 'serial one-loop')+' source → Fourier h2/h1 ratio and complete numerator → '+('all four ordinary corners plus evaluated H(3e), then beta3/chi2 finite assembly' if opposite else 'two explicit endpoint primitives, then alpha4 finite assembly')+' → native residual sign, orbit/crossing and full '+('AA/Af/Ff A+B/U' if pi2 else 'AA/Af/ff B1²')+' colour convolution.'
            ev += [evidence(p,'The complete source tensor gives two coordinate terms','full transverse Fourier tensor connection'),evidence(p,'The source order is','own original ordered bounds and separation'),evidence(p,r'z^{3e}-0-0+1' if opposite else r'J_A=\frac{(2+e)z^{3e}}','actual ordinary corner or endpoint evaluation'),evidence(p,r'\chi_2=' if opposite else r'\alpha_4=112','explicit highest required finite assembly'),evidence(p,'F_c(0)=','complete colour finite Cauchy sum')]
            shared=FAMILY/'chains-pi2.md';ev += [evidence(shared,r'\frac{h_2}{h_1}','Fourier Gamma recurrence'),evidence(shared,'N=(1+4e)','actual Gram/full-numerator bridge')]
            if opposite:ev.append(evidence(shared,'M_{2,1}={}&','complete needed M/HLOG values'))
            if pi2:ev += [evidence(shared,'A_{AA}&=','full accepted Pi2 rational operator'),evidence(shared,r'b_{c,-3}\bar u_5','fifth-order inverse-U budget before cancellation')]
            adoption='Full native '+('D-dimensional bare Pi2 A/B operator' if pi2 else 'internal one-loop Pi1 operator')+' is an accepted initial physical source, not reintegrated. '+('The established four M evaluations for the opposite body are adopted completely.' if opposite else 'The endpoint body needs no evaluated M integral.')
            equality='Native C/J proves equal endpoint J but opposite scalar signs for the corresponding chain/Pi2 geometry. Their outside operators and physical coloured contributions remain different.'
        source={'input_path':(own/'input.json').relative_to(ROOT).as_posix(),'input_sha256':sha(own/'input.json'),'data_index_path':(own/'data/index.json').relative_to(ROOT).as_posix(),'data_index_sha256':sha(own/'data/index.json'),'bindings':inp['source_bindings'],'native_normalization':inp['native_normalization'],'evaluated_quantity_normalization':inp['evaluated_quantity_normalization']}
        rows.append({'orbit_id':oid,'family':route,'document_status':'正文可连续阅读（接受明确的物理算符根）' if direct else '明确采用已求函数引理，链已接通','mathematical_chain':chain,'explicit_adoption':adoption,'equality_scope':equality,'evidence':ev,'source_binding_evidence':source,'five_dimensions':{'prose':'Own starting integral, specific reduction, evaluated subintegrals and finite scalar/colour assembly are connected by the cited mathematical passages.','implementation':'Inspected actual original-source checks, Gamma/moment reconstruction and complete operator convolutions. Six Pi1 route reductions are analytically adopted formulas; code does not derive them anew.','reproduction':'Actual primary and copied-closure batch runs passed; counts in the separate integrator receipt are batch totals.','mathematical_validation':'Research-level exact adopted calculations and scoped controls; formal=not_run, no second independent internal loop/whole-integral evaluation.','publication':'Current local reader; this task performs no Git/publication or selector change.'},'remaining_document_or_implementation_gaps':[]})
    report={'format':'wilson-integral-derivation-scientific-review/1','date':'2026-11-04','reviewer':'/root/insertion_review','standard_version':'1.0','status':'all_15_continuity_accepted_with_explicit_adoptions','scope':'Independent forward reading of all15 own articles, three shared mathematical derivations, complete adopted moment expressions and actual code/data roles. No cold CAS or new formal proof.','entries':rows,'open_findings':[],
      'resolved_findings':['Old route-result statements expanded into concrete own endpoint/face/crossing derivations.','Historical positive r001 Pi1 physical-I signs were not transferred; current native C fixes every scalar sign.','False full-transverse |N|<=CD corner bound replaced by bounded N and D^(-2+2Ree), proving only the stated positive-regulator starting strip.','Full M/rho1 HLOG evaluations and all six Pi2 A/B rational functions printed instead of opaque function/dictionary pointers.','Unused H/rho adoption paragraphs removed from the four elementary Pi1 Gamma/Beta bodies.','Batch-global function reads are distinguished from graph-specific mathematical dependencies; adjacent H0 batch budgets are explicitly scoped.'],
      'reviewer_executed_checks':{'path':'review/math-transcription-check.json','status':transcription['status'],'expressions':transcription['expressions'],'HLOG_coordinate_positions':transcription['HLOG_nonzero_coordinate_positions'],'scope':transcription['scope']},'integrator_executed_checks':{'path':'workflow/checks/integral-documentation-insertions-20261104/replay.json',**{k:replay[k] for k in ['status','entries','scalar_or_geometric_positions','generated_colour_positions','historical_colour_positions_compared','function_representation_positions','source_orbits','paired_polynomial_integrals','Gamma_finite_controls','negative_controls','isolation']}},'standard_decision':'Retain standard1.0. Exact source/function adoption is explicit; graph-specific reductions and corner conditions were not waived.'}
    (HERE/'audit.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    text=['# Scientific reading audit: all15 insertion entries','','All15 articles now connect their own initial ordered integral to the complete scalar/geometric Laurent series and external colour finite coefficient. Physical source operators and already evaluated functions remain explicitly adopted inputs. This is an independent scientific reading/implementation audit; it is not15 new independent integrations.','','| Entry | Route | Reading status |','|---|---|---|']
    for row in rows:text.append(f"| [{row['orbit_id']}](../../../../integrals/three-loop/{row['orbit_id']}/derivation.md) | {row['family']} | {row['document_status']} |")
    text += ['','The exact [per-entry evidence](audit.json) identifies the actual mathematical passages, their source/input bindings and five acceptance dimensions. Six endpoint bodies are elementary Gamma/Beta calculations from the accepted operator roots; nine additionally use explicitly evaluated M or ordered-body lemmas. No acceptance is inferred from headings, file count or old tables.','','## Findings and difficult steps','','The full opposite Pi1 numerator tends to `(1-2e)z`, not zero, at its zero corner. A draft assertion `|N|<=C D` was false. The corrected full density is bounded by `C D^(-2+2Re e)`; with the two-dimensional measure its radial integral is `r^(-1+2Re e)dr`, integrable strictly on the positive starting strip. Holomorphy of the weaker weighted H body is proved separately. This concrete mathematical correction matters even though all saved coefficients already matched.','','P3 retains its weighted derivative boundary/Beta mass; P5 retains all eight inner/outer rectangle terms and uses the mixed T first derivative only to the required order; P6 retains its independent-square derivative corner mass. The article-specific maps justify physical-I aliases without silently equating all bare J functions. Historical pre-migration scalar signs were excluded from current normalization.','','The chain and Pi2 bodies use the complete transverse tensor and all four opposite corners. They share endpoint J but have different native scalar signs and different outside operators. Pi2 retains its actual AA/Af/Ff channels; the serial chain has AA/Af/ff. The fifth-order inverse-U coefficient is required before the regular Pi2 multiplier is truncated to order four. Source operators, geometric I and full colours are never identified with one another.','','The new data indices distinguish mathematically needed moments from functions loaded globally by a batch, and identify adopted internal operators separately from whole-I comparison targets. The generator reads no complete-I reference or old operator-expansion table. Its actual role is source checks plus established analytic reductions, Gamma/moment expansion and complete operator convolution, without a fresh CAS integration.','','## Actual checks and their limits','',f"The reviewer executed [21 printed-expression checks](math-transcription-check.json) with [the saved script](check_math_transcription.py): ten native M expressions, one full rho1, four alternative LaTeX M expressions and six Pi2 A/B rational expressions. All match their declared frozen inputs, covering107 nonzero HLOG-coordinate positions (counting the two printed presentations separately). This is transcription validation, not independent verification of the original integrations.",'', 'The integrator receipt reports105 scalar/geometric positions,238 newly assembled colour positions and343 representation substitutions. Only84 old colour positions are actually present for reference comparison; the154 Pi1 colour positions are not mislabelled as old-table checks. The separate controls cover15 sources,30 polynomial integrations,six Gamma finite controls and six negative controls. These are scoped batch totals, and the other nine roots have no new original-multidimensional finite numerical control. The relocated generation ran without final references, and all15 scalar/colour payloads and complete generated JSON matched the primary run.','','All conclusions retain fixed positive real z, stated local regulator continuation, adopted QFT/internal-operator roots and original function-evaluation scope. No new general complex-z, z=-1, strict numerical enclosure or Lean integral theorem is granted. No Git/publication/selector action belongs to this audit.','','## Standard decision','','Keep standard1.0 unchanged. The nontrivial source-to-formula links, nonzero derivative boundaries, complete evaluated function values and pole-dependent assembly budgets are practical requirements. Exact prior adoption is acceptable when its mathematical statement is complete; a successful script or hash alone cannot fill that statement. See the [baseline](baseline-findings.md) and [standard lessons](standard-lessons.md).','']
    (HERE/'README.md').write_text('\n'.join(text),encoding='utf-8')
    print({'entries':len(rows),'status':report['status'],'reviewed_passages':sum(len(r['evidence']) for r in rows)})
